import json,pathlib,subprocess,os,hashlib,fcntl,base64,urllib.request
root=pathlib.Path('/opt/tp-community-actions');sha='d53b0dfe7f470d8ee5ead5c5753024923367f3ee'
release=root/'backend-releases'/sha
with (root/'deployment.lock').open('a') as lock:
 fcntl.flock(lock,fcntl.LOCK_EX)
 rollback=json.loads((release/'rollback.json').read_text())
 live=json.load(urllib.request.urlopen('http://127.0.0.1:9999/api/v1/sys_version',timeout=5))['data']['version']
 assert live==rollback['restored_version']
 manifest=json.loads((release/'manifest.json').read_text());assert manifest['commit']==sha
 migration=release/'sql/broker/017_delegated_routes.sql'
 raw=migration.read_bytes();assert hashlib.sha256(raw).hexdigest()==manifest['sha256']['sql/broker/017_delegated_routes.sql']
 sql=b"BEGIN; SET LOCAL lock_timeout='10s'; SET LOCAL statement_timeout='30s';\n"+raw+b'\nCOMMIT;'
 p=subprocess.run(['docker','exec','-i','timescaledb','psql','-X','-q','-v','ON_ERROR_STOP=1','-U','postgres','-d','ThingsPanel'],input=sql,stdout=subprocess.PIPE,stderr=subprocess.PIPE)
 assert p.returncode==0,'Broker migration 017 failed'
 archive=release.with_name(sha+'.attempt1');assert not archive.exists();os.rename(str(release),str(archive))
for name,encoded in {'deploy_encore.py': '', 'deployment_guard.py': '', 'encore_migrations.py': '', 'encore_artifacts.py': '', 'automation_tick.py': '', 'notification_identity.py': ''}.items():
 path=root/'incoming'/name;path.write_bytes(base64.b64decode(encoded));path.chmod(0o600)
p=subprocess.run(['python3',str(root/'incoming/deploy_backend.py'),sha],stdout=subprocess.PIPE,stderr=subprocess.PIPE,universal_newlines=True,timeout=180)
if p.returncode:
 print(json.dumps({'status':'failed','step':'backend-retry','error':p.stderr[-3000:]}));raise SystemExit(1)
print(json.dumps({'status':'backend-main-deployed','commit':sha,'broker_migration':17}),flush=True)
